WITH selected AS (SELECT * FROM public.indicator_series WHERE series_key IN ('education.postwar.secondary_students1946_1956','education.postwar.university1976.total','education.postwar.university1976.female','education.modern.placement.employment_share','education.modern.placement.graduates','education.modern.placement.employed','vivid.groups.education.employed','vivid.groups.education.population'))
SELECT jsonb_build_object('captured_at',now(),'series',(SELECT jsonb_agg(to_jsonb(s)-'created_at'-'updated_at' ORDER BY series_key) FROM selected s),'observations',(SELECT jsonb_agg(jsonb_build_object('series_key',v.series_key,'year',year,'group_key',group_key,'group_label',group_label,'value',value,'value_kind',value_kind,'validation_status',validation_status,'source_url',v.source_url,'meta',meta) ORDER BY v.series_key,group_key,year) FROM public.indicator_values v JOIN selected s USING(series_key) WHERE v.is_published AND v.value IS NOT NULL AND ((v.series_key LIKE 'education.postwar.%' AND year BETWEEN 1946 AND 1975) OR (v.series_key LIKE 'education.modern.%' AND year BETWEEN 2009 AND 2024) OR (v.series_key LIKE 'vivid.groups.%' AND ((group_key LIKE 'FI|%' AND year BETWEEN 1995 AND 2024) OR (group_key LIKE 'MK%' AND year=2024)))))) payload
